+			    u64 len, struct fastrpc_phy_page *pages)
+{
+	struct drm_gem_object *gem_obj;
+	struct qda_gem_obj *qda_gem_obj;
+	int err;
+
+	if (!gem_handle) {
+		pages->addr = 0;
+		pages->size = 0;
